import {dispatchAction} from './registry.mjs';
const context=Object.freeze({surface:'ui',actor:'human',runtime:'browser',mode:'paper'});
const run=(id,input)=>dispatchAction(id,input,context);
export {DEFAULT_MODEL_CONFIG,MODEL_ASSUMPTIONS} from '../trading/model.mjs';
export {DEFAULT_PAPER_POLICY,validatePaperAccount,validatePaperPolicy} from '../trading/runtime.mjs';
export {createKnowledge,validateKnowledge} from '../knowledge.mjs';
export const precomputeFeatures=(dataset,options={})=>run('market.features',{dataset,...options});
export const decideSnapshot=(feature,options={})=>run('decision.reference',{feature,...options});
export const createPaperAccount=(options={})=>run('portfolio.create.paper',options);
export const accountMetrics=(account,price)=>run('portfolio.metrics',{account,price});
export const markPaperAccount=(account,observation)=>run('portfolio.mark',{account,...observation});
export const preparePaperOrder=input=>run('order.prepare.paper',input);
export const executePaperOrder=input=>run('order.paper.execute',input);
export const compareTradingModels=(dataset,options={})=>run('strategy.compare',{dataset,...options});
export const buildContext=knowledge=>run('knowledge.context',{knowledge});
export const addKnowledge=(knowledge,item,options)=>run('knowledge.add',{knowledge,item,...(options?{options}:{})});
export const updateKnowledge=(knowledge,id,patch,options)=>run('knowledge.update',{knowledge,id,patch,...(options?{options}:{})});
export const reviewKnowledge=(knowledge,id,review,options)=>run('knowledge.review',{knowledge,id,review,...(options?{options}:{})});
export const importKnowledge=raw=>run('knowledge.import.preview',{raw});
